/**
 * Alignment Controls Component
 *
 * Provides quick alignment buttons for elements.
 * Supports left, center, right, and justify alignment.
 *
 * @module components/editor/AlignmentControls
 */

'use client';

import React from 'react';
import { AlignLeft, AlignCenter, AlignRight, AlignJustify } from 'lucide-react';
import type { Alignment } from '@/types/slide-subtypes';

interface AlignmentControlsProps {
  currentAlignment?: Alignment;
  onChange: (alignment: Alignment) => void;
  elementName: string;
  className?: string;
}

const alignments: { value: Alignment; icon: React.ReactNode; label: string }[] = [
  { value: 'left', icon: <AlignLeft className="w-4 h-4" />, label: 'Left' },
  { value: 'center', icon: <AlignCenter className="w-4 h-4" />, label: 'Center' },
  { value: 'right', icon: <AlignRight className="w-4 h-4" />, label: 'Right' },
  { value: 'justify', icon: <AlignJustify className="w-4 h-4" />, label: 'Justify' },
];

/**
 * Alignment Controls Component
 *
 * Provides a simple toolbar for quickly changing text alignment.
 * Shows visual preview of each alignment option.
 */
export const AlignmentControls: React.FC<AlignmentControlsProps> = ({
  currentAlignment = 'left',
  onChange,
  elementName,
  className = '',
}) => {
  return (
    <div className={`space-y-2 ${className}`}>
      <label className="block text-sm font-medium text-white/70">
        {elementName} Alignment
      </label>

      <div className="flex gap-1">
        {alignments.map((alignment) => {
          const isSelected = currentAlignment === alignment.value;

          return (
            <button
              key={alignment.value}
              type="button"
              onClick={() => onChange(alignment.value)}
              className={`flex-1 p-2 rounded-lg transition-all duration-200 relative overflow-hidden ${
                isSelected
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30'
                  : 'bg-white/10 text-white/70 hover:bg-white/15 hover:text-white'
              }`}
              title={`${alignment.label} alignment`}
            >
              <div className="flex items-center justify-center gap-2">
                {alignment.icon}
                <span className="text-xs font-medium">{alignment.label}</span>
              </div>

              {/* Preview lines */}
              <div className="mt-1.5 flex gap-0.5 justify-center opacity-50">
                {alignment.value === 'left' && (
                  <>
                    <div className="w-8 h-0.5 bg-current rounded-l" />
                    <div className="w-6 h-0.5 bg-current rounded-l" />
                    <div className="w-4 h-0.5 bg-current rounded-l" />
                  </>
                )}
                {alignment.value === 'center' && (
                  <>
                    <div className="w-4 h-0.5 bg-current rounded" />
                    <div className="w-6 h-0.5 bg-current rounded" />
                    <div className="w-4 h-0.5 bg-current rounded" />
                  </>
                )}
                {alignment.value === 'right' && (
                  <>
                    <div className="w-4 h-0.5 bg-current rounded-r" />
                    <div className="w-6 h-0.5 bg-current rounded-r" />
                    <div className="w-8 h-0.5 bg-current rounded-r" />
                  </>
                )}
                {alignment.value === 'justify' && (
                  <>
                    <div className="w-8 h-0.5 bg-current" />
                    <div className="w-8 h-0.5 bg-current" />
                    <div className="w-8 h-0.5 bg-current" />
                  </>
                )}
              </div>
            </button>
          );
        })}
      </div>

      {/* Apply to All Button */}
      <div className="pt-2 border-t border-white/10">
        <button
          type="button"
          onClick={() => onChange(currentAlignment)}
          className="w-full px-3 py-2 text-xs text-white/60 hover:text-white hover:bg-white/10 rounded-lg transition-colors"
        >
          Apply {elementName} Alignment Only
        </button>
      </div>
    </div>
  );
};

export default AlignmentControls;