/**
 * Element Position Controls Component
 *
 * Provides controls for customizing element positioning and alignment.
 * Supports auto, absolute, and relative positioning modes.
 *
 * @module components/editor/ElementPositionControls
 */

'use client';

import React from 'react';
import { RotateCcw, AlignLeft, AlignCenter, AlignRight, AlignJustify } from 'lucide-react';
import type { ElementPosition, Alignment, PositionMode } from '@/types/slide-subtypes';

interface ElementPositionControlsProps {
  position?: ElementPosition;
  onChange: (position: ElementPosition) => void;
  elementName: string;
  className?: string;
}

/**
 * Element Position Controls Component
 *
 * Provides comprehensive controls for element positioning including:
 * - Position mode selection (auto/absolute/relative)
 * - Alignment buttons (left/center/right/justify)
 * - X/Y coordinates (for absolute mode)
 * - Width/height sliders
 * - Spacing controls (margins)
 * - Z-index input
 * - Reset to defaults button
 */
export const ElementPositionControls: React.FC<ElementPositionControlsProps> = ({
  position,
  onChange,
  elementName,
  className = '',
}) => {
  const [localPosition, setLocalPosition] = React.useState<ElementPosition>(
    position || { mode: 'auto', alignment: 'center' }
  );

  // Update local position when props change
  React.useEffect(() => {
    if (position) {
      setLocalPosition(position);
    }
  }, [position]);

  // Handle mode change
  const handleModeChange = (mode: PositionMode) => {
    const newPosition: ElementPosition = {
      ...localPosition,
      mode,
      // Reset to defaults when changing mode
      alignment: mode === 'auto' ? 'center' : localPosition.alignment,
    };
    setLocalPosition(newPosition);
    onChange(newPosition);
  };

  // Handle alignment change
  const handleAlignmentChange = (alignment: Alignment) => {
    const newPosition: ElementPosition = {
      ...localPosition,
      alignment,
    };
    setLocalPosition(newPosition);
    onChange(newPosition);
  };

  // Handle coordinate change
  const handleCoordinateChange = (field: 'x' | 'y', value: number) => {
    const newPosition: ElementPosition = {
      ...localPosition,
      [field]: value,
    };
    setLocalPosition(newPosition);
    onChange(newPosition);
  };

  // Handle size change
  const handleSizeChange = (field: 'width' | 'height', value: number) => {
    const newPosition: ElementPosition = {
      ...localPosition,
      [field]: value,
    };
    setLocalPosition(newPosition);
    onChange(newPosition);
  };

  // Handle margin change
  const handleMarginChange = (field: keyof Pick<ElementPosition, 'marginTop' | 'marginBottom' | 'marginLeft' | 'marginRight'>, value: number) => {
    const newPosition: ElementPosition = {
      ...localPosition,
      [field]: value,
    };
    setLocalPosition(newPosition);
    onChange(newPosition);
  };

  // Handle z-index change
  const handleZIndexChange = (value: number) => {
    const newPosition: ElementPosition = {
      ...localPosition,
      zIndex: value,
    };
    setLocalPosition(newPosition);
    onChange(newPosition);
  };

  // Reset to defaults
  const handleReset = () => {
    const defaultPosition: ElementPosition = {
      mode: 'auto',
      alignment: 'center',
    };
    setLocalPosition(defaultPosition);
    onChange(defaultPosition);
  };

  const isAbsolute = localPosition.mode === 'absolute';
  const isRelative = localPosition.mode === 'relative';

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-medium text-white/90">
          Positioning: {elementName}
        </h4>
        <button
          type="button"
          onClick={handleReset}
          className="flex items-center gap-1 px-2 py-1 text-xs text-white/60 hover:text-white hover:bg-white/10 rounded transition-colors"
          title="Reset to defaults"
        >
          <RotateCcw className="w-3 h-3" />
          Reset
        </button>
      </div>

      {/* Position Mode */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Position Mode
        </label>
        <div className="flex gap-2">
          {(['auto', 'absolute', 'relative'] as const).map((mode) => (
            <button
              key={mode}
              type="button"
              onClick={() => handleModeChange(mode)}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                localPosition.mode === mode
                  ? 'bg-blue-600 text-white'
                  : 'bg-white/10 text-white/70 hover:bg-white/15'
              }`}
            >
              {mode.charAt(0).toUpperCase() + mode.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Alignment */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Text Alignment
        </label>
        <div className="flex gap-1">
          {(['left', 'center', 'right', 'justify'] as const).map((alignment) => (
            <button
              key={alignment}
              type="button"
              onClick={() => handleAlignmentChange(alignment)}
              className={`flex-1 p-2 rounded-md transition-colors ${
                localPosition.alignment === alignment
                  ? 'bg-white/20 text-white'
                  : 'bg-white/5 text-white/50 hover:bg-white/10'
              }`}
              title={`${alignment.charAt(0).toUpperCase() + alignment.slice(1)}`}
            >
              {alignment === 'left' && <AlignLeft className="w-4 h-4 mx-auto" />}
              {alignment === 'center' && <AlignCenter className="w-4 h-4 mx-auto" />}
              {alignment === 'right' && <AlignRight className="w-4 h-4 mx-auto" />}
              {alignment === 'justify' && <AlignJustify className="w-4 h-4 mx-auto" />}
            </button>
          ))}
        </div>
      </div>

      {/* Absolute Positioning Controls */}
      {isAbsolute && (
        <>
          <div className="grid grid-cols-2 gap-4">
            {/* X Coordinate */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                X Position (%)
              </label>
              <input
                type="number"
                min="0"
                max="100"
                value={localPosition.x ?? 50}
                onChange={(e) => handleCoordinateChange('x', Number(e.target.value))}
                className="w-full px-3 py-1.5 bg-white/10 border border-white/20 rounded-lg text-white text-sm focus:outline-none focus:border-white/40"
              />
            </div>

            {/* Y Coordinate */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Y Position (%)
              </label>
              <input
                type="number"
                min="0"
                max="100"
                value={localPosition.y ?? 50}
                onChange={(e) => handleCoordinateChange('y', Number(e.target.value))}
                className="w-full px-3 py-1.5 bg-white/10 border border-white/20 rounded-lg text-white text-sm focus:outline-none focus:border-white/40"
              />
            </div>
          </div>

          {/* Width */}
          <div>
            <label className="block text-xs font-medium text-white/60 mb-2">
              Width (%)
            </label>
            <input
              type="range"
              min="10"
              max="100"
              value={localPosition.width ?? 100}
              onChange={(e) => handleSizeChange('width', Number(e.target.value))}
              className="w-full"
            />
            <div className="flex justify-between text-xs text-white/50 mt-1">
              <span>10%</span>
              <span>{localPosition.width ?? 100}%</span>
              <span>100%</span>
            </div>
          </div>

          {/* Height */}
          <div>
            <label className="block text-xs font-medium text-white/60 mb-2">
              Height (%)
            </label>
            <input
              type="range"
              min="10"
              max="100"
              value={localPosition.height ?? 100}
              onChange={(e) => handleSizeChange('height', Number(e.target.value))}
              className="w-full"
            />
            <div className="flex justify-between text-xs text-white/50 mt-1">
              <span>10%</span>
              <span>{localPosition.height ?? 100}%</span>
              <span>100%</span>
            </div>
          </div>
        </>
      )}

      {/* Margins */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Spacing (px)
        </label>
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs text-white/40 mb-1">Top</label>
            <input
              type="number"
              min="0"
              max="200"
              value={localPosition.marginTop ?? 0}
              onChange={(e) => handleMarginChange('marginTop', Number(e.target.value))}
              className="w-full px-2 py-1 bg-white/10 border border-white/20 rounded text-white text-xs focus:outline-none focus:border-white/40"
            />
          </div>
          <div>
            <label className="block text-xs text-white/40 mb-1">Bottom</label>
            <input
              type="number"
              min="0"
              max="200"
              value={localPosition.marginBottom ?? 0}
              onChange={(e) => handleMarginChange('marginBottom', Number(e.target.value))}
              className="w-full px-2 py-1 bg-white/10 border border-white/20 rounded text-white text-xs focus:outline-none focus:border-white/40"
            />
          </div>
          <div>
            <label className="block text-xs text-white/40 mb-1">Left</label>
            <input
              type="number"
              min="0"
              max="200"
              value={localPosition.marginLeft ?? 0}
              onChange={(e) => handleMarginChange('marginLeft', Number(e.target.value))}
              className="w-full px-2 py-1 bg-white/10 border border-white/20 rounded text-white text-xs focus:outline-none focus:border-white/40"
            />
          </div>
          <div>
            <label className="block text-xs text-white/40 mb-1">Right</label>
            <input
              type="number"
              min="0"
              max="200"
              value={localPosition.marginRight ?? 0}
              onChange={(e) => handleMarginChange('marginRight', Number(e.target.value))}
              className="w-full px-2 py-1 bg-white/10 border border-white/20 rounded text-white text-xs focus:outline-none focus:border-white/40"
            />
          </div>
        </div>
      </div>

      {/* Z-Index */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Layer Order (Z-Index)
        </label>
        <input
          type="number"
          min="0"
          max="100"
          value={localPosition.zIndex ?? 10}
          onChange={(e) => handleZIndexChange(Number(e.target.value))}
          className="w-full px-3 py-1.5 bg-white/10 border border-white/20 rounded-lg text-white text-sm focus:outline-none focus:border-white/40"
        />
        <div className="flex items-center gap-2 mt-2">
          <div className="flex-1 h-1 bg-white/20 rounded">
            <div
              className="h-full bg-blue-500 rounded"
              style={{ width: `${((localPosition.zIndex || 10) / 100) * 100}%` }}
            />
          </div>
          <span className="text-xs text-white/50">{localPosition.zIndex || 10}</span>
        </div>
      </div>

      {/* Info */}
      <div className="p-3 bg-white/5 rounded-lg">
        <p className="text-xs text-white/60">
          <strong className="text-white/80">Positioning Modes:</strong>
        </p>
        <ul className="mt-2 space-y-1 text-xs text-white/50">
          <li>
            <strong>Auto:</strong> Uses standard layout with alignment
          </li>
          <li>
            <strong>Absolute:</strong> Custom X/Y coordinates (0-100%)
          </li>
          <li>
            <strong>Relative:</strong> Offset from auto position
          </li>
        </ul>
      </div>
    </div>
  );
};

export default ElementPositionControls;