'use client';

import React from 'react';
import dynamic from 'next/dynamic';
import { useCarouselStore } from '@/store/carousel-store';
import { useCanvasStore } from '@/store/canvas-store';
import { ArcTemplateSelector } from './ArcTemplateSelector';
import { SlideEditor } from './SlideEditor';
import { ThemedSlide } from '../preview/ThemedSlide';
import { PropertyPanel } from './PropertyPanel';
import { LayerPanel } from './LayerPanel';
import { Toolbar } from './Toolbar';
import { ZoomControls } from './ZoomControls';
import { PresetManager } from './PresetManager';
import { PREVIEW_SCALE, SLIDE_WIDTH, SLIDE_HEIGHT } from '@/config/constants';
import { Plus, GripVertical, Settings2, Layers, Undo, Redo, Trash2 } from 'lucide-react';
import { CanvasElement } from '@/types/canvas-elements';
import { cn } from '@/lib/utils';

// Phase 4: Tooltip and ToolButton components (reused from Toolbar)
const Tooltip: React.FC<{ content: string; children: React.ReactNode }> = ({ content, children }) => {
  return (
    <div className="relative group">
      {children}
      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 bg-black/90 text-white text-xs rounded whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
        {content}
        <div className="absolute top-full left-1/2 -translate-x-1/2 -mt-0.5 border-4 border-transparent border-t-black/90" />
      </div>
    </div>
  );
};

const ToolButton: React.FC<{
  icon: React.ReactNode;
  active?: boolean;
  disabled?: boolean;
  danger?: boolean;
  onClick: () => void;
  'aria-label': string;
}> = ({ icon, active = false, disabled = false, danger = false, onClick, 'aria-label': ariaLabel }) => {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      aria-label={ariaLabel}
      className={cn(
        'p-2 rounded-lg transition-all duration-200',
        'flex items-center justify-center',
        'min-w-[36px] min-h-[36px]',
        // Base styles
        !disabled && !active && !danger && 'bg-white/5 text-white/70 hover:bg-white/10 hover:text-white',
        // Active styles
        active && 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30',
        // Danger styles
        danger && !disabled && 'bg-red-500/20 text-red-400 hover:bg-red-500/30',
        // Disabled styles
        disabled && 'bg-white/5 text-white/30 cursor-not-allowed opacity-50',
        // Icon styles
        'w-9 h-9'
      )}
    >
      {icon}
    </button>
  );
};

// Dynamically import CanvasSlide with SSR disabled to prevent canvas package requirement
const CanvasSlideEditor = dynamic(
  () => import('../preview/CanvasSlide').then(mod => ({ default: mod.CanvasSlideEditor })),
  { ssr: false }
);
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Slide } from '@/types/index';
import { cn } from '@/lib/utils';

interface SortableSlideItemProps {
  slide: Slide;
  isSelected: boolean;
  onSelect: () => void;
  pillar: string;
  totalSlides: number;
  carouselBackgroundPack?: string;
}

function SortableSlideItem({ slide, isSelected, onSelect, pillar, totalSlides, carouselBackgroundPack }: SortableSlideItemProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: slide.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  // Calculate scale to fit within the sidebar width (w-80 = 320px, minus padding ≈ 280px)
  // Original slide is 1080px, so scale = 280 / 1080 ≈ 0.26
  const LIST_PREVIEW_SCALE = 0.26;

return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        'relative cursor-pointer rounded-lg overflow-hidden border-2 transition-all',
        isSelected ? 'border-white' : 'border-transparent hover:border-white/30'
      )}
      onClick={onSelect}
    >
      <div
        {...attributes}
        {...listeners}
        className="absolute top-2 left-2 z-10 p-1 bg-black/50 rounded cursor-grab active:cursor-grabbing"
      >
        <GripVertical className="w-4 h-4 text-white/70" />
      </div>
      <div className="absolute top-2 right-2 z-10 px-2 py-1 bg-black/50 rounded text-xs text-white/70">
        {slide.order + 1}
      </div>
      <div
        className="bg-gray-900 flex items-center justify-center"
        style={{
          width: SLIDE_WIDTH * LIST_PREVIEW_SCALE,
          height: SLIDE_HEIGHT * LIST_PREVIEW_SCALE,
        }}
      >
        <div
          style={{
            transform: `scale(${LIST_PREVIEW_SCALE})`,
            transformOrigin: 'center center',
          }}
        >
          <ThemedSlide
            slide={slide}
            pillar={pillar as any}
            isPreview
            carouselTotalSlides={totalSlides}
            carouselBackgroundPack={carouselBackgroundPack}
          />
        </div>
      </div>
    </div>
  );
}

export function CarouselEditor() {
  const {
    carousel,
    selectedSlideId,
    selectSlide,
    addSlide,
    reorderSlides,
  } = useCarouselStore();

  const { selectedIds, deselectAll } = useCanvasStore();

  // Canvas mode state
  const [canvasMode, setCanvasMode] = React.useState(false);
  const [showPropertyPanel, setShowPropertyPanel] = React.useState(true);
  const [showLayerPanel, setShowLayerPanel] = React.useState(false);

  // Phase 4: Canvas elements state (for PropertyPanel and LayerPanel)
  const [canvasElements, setCanvasElements] = React.useState<Map<string, CanvasElement>>(new Map());
  const [canvasElementsRef, setCanvasElementsRef] = React.useState<React.RefObject<any>>(React.createRef());

  // Phase 4: Handler for element updates from PropertyPanel
  const handleCanvasElementUpdate = React.useCallback((elementId: string, updates: Partial<CanvasElement>) => {
    console.log('[CarouselEditor] Canvas element update:', elementId, updates);
    // The update will be handled by the CanvasSlide component
    // We need to pass this through to CanvasSlide
    if (canvasElementsRef.current) {
      const canvasSlide = (canvasElementsRef.current as any).handleElementUpdate;
      if (canvasSlide) {
        canvasSlide(elementId, updates);
      }
    }
  }, [canvasElementsRef]);

  // Phase 4: Handler for element deletion from LayerPanel or Toolbar
  const handleCanvasElementDelete = React.useCallback((elementId: string) => {
    console.log('[CarouselEditor] Canvas element delete:', elementId);
    // The delete will be handled by the CanvasSlide component
    if (canvasElementsRef.current) {
      const canvasSlide = (canvasElementsRef.current as any).handleElementDelete;
      if (canvasSlide) {
        canvasSlide(elementId);
      }
    }
    deselectAll();
  }, [canvasElementsRef, deselectAll]);

  // Phase 4: Handler for elements change from CanvasSlide
  const handleElementsChange = React.useCallback((elements: CanvasElement[]) => {
    const elementsMap = new Map(elements.map(e => [e.id, e]));
    setCanvasElements(elementsMap);
  }, []);

  // Phase 4: Undo handler (placeholder - to be implemented in carousel-store)
  const handleUndo = React.useCallback(() => {
    console.log('[CarouselEditor] Undo clicked');
    // TODO: Implement undo functionality in carousel-store
  }, []);

  // Phase 4: Redo handler (placeholder - to be implemented in carousel-store)
  const handleRedo = React.useCallback(() => {
    console.log('[CarouselEditor] Redo clicked');
    // TODO: Implement redo functionality in carousel-store
  }, []);

  // Phase 4: Delete selected elements handler
  const handleDeleteSelected = React.useCallback(() => {
    console.log('[CarouselEditor] Delete selected elements:', selectedIds);
    selectedIds.forEach(id => handleCanvasElementDelete(id));
  }, [selectedIds, handleCanvasElementDelete]);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      reorderSlides(active.id as string, over.id as string);
    }
  };

  const handleAddSlide = () => {
    addSlide({
      type: 'content',
      content: {
        headline: 'New Slide',
        subtext: 'Edit this content...',
      },
    });
  };

  if (!carousel) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-white/60">No carousel loaded</p>
      </div>
    );
  }

  const selectedSlide = carousel.slides.find((s) => s.id === selectedSlideId);

  return (
    <div className="flex h-full gap-4">
      {/* Slide List Sidebar - Left Panel */}
      <div
        className="w-80 flex-shrink-0 bg-white/5 rounded-xl overflow-hidden flex flex-col"
        style={{ minHeight: 0 }}
      >
        <div className="p-4 border-b border-white/10 flex-shrink-0">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-medium text-white">Slides</h2>
            <span className="text-sm text-white/50">
              {carousel.slides.length}/10
            </span>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-4" style={{ minHeight: 0 }}>
          <div className="space-y-4">

          <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
          >
            <SortableContext
              items={carousel.slides.map((s) => s.id)}
              strategy={verticalListSortingStrategy}
            >
              <div className="space-y-2">
                {carousel.slides.map((slide) => (
                  <SortableSlideItem
                    key={slide.id}
                    slide={slide}
                    isSelected={slide.id === selectedSlideId}
                    onSelect={() => selectSlide(slide.id)}
                    pillar={carousel.pillar}
                    totalSlides={carousel.slides.length}
                    carouselBackgroundPack={carousel.carouselBackgroundPack}
                  />
                ))}
              </div>
            </SortableContext>
          </DndContext>

          {carousel.slides.length < 10 && (
            <button
              onClick={handleAddSlide}
              className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-white/5 hover:bg-white/10 rounded-lg text-white/70 hover:text-white transition-colors"
            >
              <Plus className="w-4 h-4" />
              Add Slide
            </button>
          )}
          </div>
        </div>
      </div>

      {/* Main Preview - Center Panel - FIXED, NO SCROLL */}
      <div className="flex-1 flex flex-col gap-4 overflow-hidden" style={{ minHeight: 0 }}>
        {/* Top Bar - Toolbar */}
        <div className="flex-shrink-0 flex items-center gap-4">
          {/* Canvas Mode Toggle */}
          <button
            onClick={() => setCanvasMode(!canvasMode)}
            className={cn(
              'flex items-center gap-2 px-4 py-2 rounded-lg transition-all',
              canvasMode
                ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                : 'bg-white/5 text-white/70 hover:bg-white/10'
            )}
          >
            <Settings2 className="w-4 h-4" />
            <span className="text-sm font-medium">
              {canvasMode ? 'Canvas Mode' : 'DOM Mode'}
            </span>
          </button>

          {/* Toolbar (only in canvas mode) */}
          {canvasMode && (
            <>
              <Toolbar
                onFitToScreen={() => {
                  // TODO: Implement fit to screen
                }}
                onToggleSnapGrid={() => {
                  // TODO: Implement snap grid toggle
                }}
                snapGridEnabled={false}
              />

              {/* Phase 4: Undo/Redo Buttons */}
              <div className="flex items-center gap-1 pl-3 border-l border-white/10">
                <Tooltip content="Undo (Ctrl+Z)">
                  <ToolButton
                    icon={<Undo className="w-4 h-4" />}
                    active={false}
                    onClick={handleUndo}
                    aria-label="Undo"
                  />
                </Tooltip>

                <Tooltip content="Redo (Ctrl+Y)">
                  <ToolButton
                    icon={<Redo className="w-4 h-4" />}
                    active={false}
                    onClick={handleRedo}
                    aria-label="Redo"
                  />
                </Tooltip>
              </div>

              {/* Phase 4: Delete Button */}
              {selectedIds.length > 0 && (
                <div className="flex items-center gap-1 pl-3 border-l border-white/10">
                  <Tooltip content={`Delete Selected (${selectedIds.length}) (Delete)`}>
                    <ToolButton
                      icon={<Trash2 className="w-4 h-4" />}
                      active={false}
                      danger={true}
                      onClick={handleDeleteSelected}
                      aria-label="Delete selected"
                    />
                  </Tooltip>
                </div>
              )}
            </>
          )}
        </div>

        {/* Preview Area */}
        <div className="flex-1 flex items-center justify-center bg-white/5 rounded-xl overflow-hidden p-4" style={{ minHeight: 0 }}>
          {selectedSlide ? (
            <div
              style={{
                transform: `scale(${PREVIEW_SCALE})`,
                transformOrigin: 'center center',
              }}
            >
              {canvasMode ? (
                <CanvasSlideEditor
                  slide={selectedSlide}
                  pillar={carousel.pillar}
                  carouselTotalSlides={carousel?.slides.length}
                  carouselBackgroundPack={carousel?.carouselBackgroundPack}
                  carouselDecoratorConfig={carousel.decoratorConfig}
                  scale={1}
                />
              ) : (
                <ThemedSlide
                  slide={selectedSlide}
                  pillar={carousel.pillar}
                  carouselTotalSlides={carousel?.slides.length}
                  carouselBackgroundPack={carousel?.carouselBackgroundPack}
                />
              )}
            </div>
          ) : (
            <p className="text-white/60">Select a slide to preview</p>
          )}
        </div>
      </div>

      {/* Editor Sidebar - Right Panel */}
      <div
        className="w-96 flex-shrink-0 bg-white/5 rounded-xl overflow-hidden flex flex-col"
        style={{ minHeight: 0 }}
      >
        {/* Sidebar Header with Toggles */}
        <div className="p-4 border-b border-white/10 flex-shrink-0">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-medium text-white">Editor</h2>
            <div className="flex items-center gap-2">
              {/* Property Panel Toggle */}
              <button
                onClick={() => setShowPropertyPanel(!showPropertyPanel)}
                className={cn(
                  'p-2 rounded-lg transition-all',
                  showPropertyPanel
                    ? 'bg-cyan-500/20 text-cyan-400'
                    : 'bg-white/5 text-white/50 hover:bg-white/10'
                )}
                title="Toggle Property Panel"
              >
                <Settings2 className="w-4 h-4" />
              </button>

              {/* Layer Panel Toggle */}
              <button
                onClick={() => setShowLayerPanel(!showLayerPanel)}
                className={cn(
                  'p-2 rounded-lg transition-all',
                  showLayerPanel
                    ? 'bg-cyan-500/20 text-cyan-400'
                    : 'bg-white/5 text-white/50 hover:bg-white/10'
                )}
                title="Toggle Layer Panel"
              >
                <Layers className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto" style={{ minHeight: 0 }}>
          <div className="space-y-6 p-4">
            {/* Preset Manager */}
            <PresetManager />

            {/* Arc Template Selector */}
            <ArcTemplateSelector />

            {/* Zoom Controls (canvas mode only) */}
            {canvasMode && (
              <div className="border-t border-white/10 pt-4">
                <ZoomControls />
              </div>
            )}

            {/* Layer Panel (canvas mode only) */}
            {/* Phase 3 Note: LayerPanel temporarily disabled
                Elements are now computed in CanvasSlide and not exposed to parent
                TODO: Implement LayerPanel integration with computed elements
            */}
            {canvasMode && showLayerPanel && (
              <div className="border-t border-white/10 pt-4">
                <div className="p-6 text-center text-white/50 text-sm">
                  <p>Layer Panel</p>
                  <p className="text-xs mt-2">
                    Layers are managed via slide editor
                  </p>
                </div>
              </div>
            )}

            {/* Property Panel (canvas mode only) */}
            {/* Phase 3 Note: PropertyPanel temporarily disabled
                Elements are now computed in CanvasSlide and not exposed to parent
                TODO: Implement PropertyPanel integration with computed elements
            */}
            {canvasMode && showPropertyPanel && (
              <div className="border-t border-white/10 pt-4">
                <div className="p-6 text-center text-white/50 text-sm">
                  <p>Property Panel</p>
                  <p className="text-xs mt-2">
                    Element properties are edited directly on the canvas
                  </p>
                </div>
              </div>
            )}

            {/* Slide Editor (DOM mode only) */}
            {!canvasMode && selectedSlide && (
              <SlideEditor slide={selectedSlide} />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
