'use client';

import React from 'react';
import { useCarouselStore } from '@/store/carousel-store';
import { arcTemplateList } from '@/config/arc-templates/titan-arc';
import { FileText } from 'lucide-react';

export function ArcTemplateSelector() {
  const { applyTemplate } = useCarouselStore();

  return (
    <div className="space-y-2">
      <label className="block text-sm font-medium text-white/70">
        Apply Template
      </label>
      <div className="flex flex-wrap gap-2">
        {arcTemplateList.map((template) => (
          <button
            key={template.id}
            onClick={() => applyTemplate(template)}
            className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-lg text-sm text-white/80 hover:text-white transition-colors"
          >
            <FileText className="w-4 h-4" />
            <div className="text-left">
              <div className="font-medium">{template.name}</div>
              <div className="text-xs text-white/50">
                {template.slides.length} slides
              </div>
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}
