import React, { useState, useCallback } from 'react';
import { useCanvasStore } from '@/store/canvas-store';
import { cn } from '@/lib/utils';

/**
 * ZoomControls component props
 */
interface ZoomControlsProps {
  className?: string;
  onFitToScreen?: () => void;
}

/**
 * ZoomControls - Zoom control panel for canvas editor
 *
 * Features:
 * - Zoom in button
 * - Zoom out button
 * - Zoom slider
 * - Zoom percentage display
 * - Fit to screen button
 * - Preset zoom levels (25%, 50%, 75%, 100%, 150%, 200%)
 */
export const ZoomControls: React.FC<ZoomControlsProps> = ({
  className,
  onFitToScreen,
}) => {
  const { zoom, setZoom } = useCanvasStore();
  const [isExpanded, setIsExpanded] = useState(false);

  /**
   * Handle zoom in
   */
  const handleZoomIn = useCallback(() => {
    const newZoom = Math.min(zoom * 1.25, 5);
    setZoom(newZoom);
  }, [zoom, setZoom]);

  /**
   * Handle zoom out
   */
  const handleZoomOut = useCallback(() => {
    const newZoom = Math.max(zoom / 1.25, 0.1);
    setZoom(newZoom);
  }, [zoom, setZoom]);

  /**
   * Handle zoom slider change
   */
  const handleZoomChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const newZoom = parseFloat(e.target.value);
    setZoom(newZoom);
  }, [setZoom]);

  /**
   * Handle preset zoom level selection
   */
  const handlePresetZoom = useCallback((preset: number) => {
    setZoom(preset);
  }, [setZoom]);

  /**
   * Handle fit to screen
   */
  const handleFitToScreen = useCallback(() => {
    onFitToScreen?.();
  }, [onFitToScreen]);

  /**
   * Get zoom percentage
   */
  const zoomPercentage = Math.round(zoom * 100);

  /**
   * Preset zoom levels
   */
  const presets = [0.25, 0.5, 0.75, 1, 1.5, 2];

  return (
    <div className={cn(
      'bg-black/20 backdrop-blur-xl border border-white/10 rounded-2xl p-3',
      'flex flex-col gap-3',
      className
    )}>
      {/* Zoom Percentage Display */}
      <div className="text-center">
        <div className="text-white font-semibold text-2xl font-mono">
          {zoomPercentage}%
        </div>
        <div className="text-white/50 text-xs uppercase tracking-wider">
          Zoom Level
        </div>
      </div>

      {/* Zoom In/Out Buttons */}
      <div className="flex items-center gap-2">
        <ZoomButton
          icon={<ZoomOutIcon />}
          onClick={handleZoomOut}
          disabled={zoom <= 0.1}
          aria-label="Zoom out"
        />

        <ZoomButton
          icon={<ZoomInIcon />}
          onClick={handleZoomIn}
          disabled={zoom >= 5}
          aria-label="Zoom in"
        />
      </div>

      {/* Zoom Slider */}
      <div className="flex items-center gap-2">
        <span className="text-white/50 text-xs">10%</span>
        <input
          type="range"
          min="0.1"
          max="5"
          step="0.05"
          value={zoom}
          onChange={handleZoomChange}
          className="flex-1 h-1.5 bg-white/20 rounded-lg appearance-none cursor-pointer accent-cyan-400"
          aria-label="Zoom level"
        />
        <span className="text-white/50 text-xs">500%</span>
      </div>

      {/* Preset Zoom Levels */}
      <div className="grid grid-cols-3 gap-1">
        {presets.map((preset) => (
          <PresetButton
            key={preset}
            percentage={preset * 100}
            active={Math.abs(zoom - preset) < 0.01}
            onClick={() => handlePresetZoom(preset)}
          />
        ))}
      </div>

      {/* Fit to Screen Button */}
      <button
        onClick={handleFitToScreen}
        disabled={!onFitToScreen}
        className={cn(
          'w-full py-2 px-3 rounded-lg transition-all duration-200',
          'flex items-center justify-center gap-2',
          'text-sm font-medium',
          !onFitToScreen && 'bg-white/5 text-white/30 cursor-not-allowed',
          onFitToScreen && 'bg-white/5 text-white/70 hover:bg-white/10 hover:text-white'
        )}
        aria-label="Fit to screen"
      >
        <FitIcon />
        <span>Fit to Screen</span>
      </button>

      {/* Reset Zoom Button */}
      <button
        onClick={() => handlePresetZoom(1)}
        className={cn(
          'w-full py-2 px-3 rounded-lg transition-all duration-200',
          'flex items-center justify-center gap-2',
          'text-sm font-medium',
          'bg-cyan-500/10 text-cyan-400 hover:bg-cyan-500/20'
        )}
        aria-label="Reset zoom to 100%"
      >
        <RefreshIcon />
        <span>Reset Zoom</span>
      </button>
    </div>
  );
};

/**
 * ZoomButton - Button component for zoom in/out
 */
interface ZoomButtonProps {
  icon: React.ReactNode;
  onClick: () => void;
  disabled?: boolean;
  'aria-label': string;
}

const ZoomButton: React.FC<ZoomButtonProps> = ({
  icon,
  onClick,
  disabled = false,
  'aria-label': ariaLabel,
}) => {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      aria-label={ariaLabel}
      className={cn(
        'flex-1 py-2 px-3 rounded-lg transition-all duration-200',
        'flex items-center justify-center',
        !disabled && 'bg-white/5 text-white/70 hover:bg-white/10 hover:text-white',
        disabled && 'bg-white/5 text-white/30 cursor-not-allowed opacity-50'
      )}
    >
      {icon}
    </button>
  );
};

/**
 * PresetButton - Button component for preset zoom levels
 */
interface PresetButtonProps {
  percentage: number;
  active?: boolean;
  onClick: () => void;
}

const PresetButton: React.FC<PresetButtonProps> = ({
  percentage,
  active = false,
  onClick,
}) => {
  return (
    <button
      onClick={onClick}
      className={cn(
        'py-1.5 px-2 rounded-lg transition-all duration-200',
        'text-xs font-mono font-medium',
        !active && 'bg-white/5 text-white/70 hover:bg-white/10 hover:text-white',
        active && 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
      )}
      aria-label={`Zoom to ${percentage}%`}
    >
      {percentage}%
    </button>
  );
};

