'use client';

import React from 'react';
import { VisualTreatmentType, TreatmentIntensity } from '@/components/visual-treatments/VisualTreatment';

interface VisualTreatmentSelectorProps {
  value?: {
    treatment: VisualTreatmentType;
    intensity: TreatmentIntensity;
    target?: 'headline' | 'subtext' | 'bullets' | 'all';
  };
  onChange: (value: {
    treatment: VisualTreatmentType;
    intensity: TreatmentIntensity;
    target?: 'headline' | 'subtext' | 'bullets' | 'all';
  }) => void;
  pillarColor?: string;
}

// All functional treatments with descriptions
const TREATMENTS = [
  { id: 'none' as const, label: 'None', description: 'No visual effect', category: 'Basic' },
  { id: 'gradient-text' as const, label: 'Gradient Text', description: 'Apply gradient to text', category: 'Modern' },
  { id: 'outline' as const, label: 'Outline', description: 'Add text outline', category: 'Modern' },
  { id: 'neon' as const, label: 'Neon', description: 'Add neon glow', category: 'Modern' },
  { id: 'holographic' as const, label: 'Holographic', description: 'Iridescent rainbow effect', category: 'Advanced' },
  { id: 'glass' as const, label: 'Glass', description: 'Frosted glass effect', category: 'Advanced' },
  { id: 'stroke-gradient' as const, label: 'Stroke Gradient', description: 'Gradient stroke with fill', category: 'Advanced' },
  { id: 'glitch' as const, label: 'Glitch', description: 'Chromatic aberration effect', category: 'Advanced' },
  { id: '3d-block' as const, label: '3D Block', description: '3D extrusion effect', category: 'Advanced' },
  { id: 'pattern-fill' as const, label: 'Pattern Fill', description: 'Pattern clipped to text', category: 'Advanced' },
  { id: 'reflection' as const, label: 'Reflection', description: 'Mirror effect below text', category: 'Advanced' },
];

const INTENSITIES: TreatmentIntensity[] = ['low', 'medium', 'high'];
const TARGETS = ['headline', 'subtext', 'bullets', 'all'] as const;

export function VisualTreatmentSelector({
  value,
  onChange,
  pillarColor = '#00E5FF',
}: VisualTreatmentSelectorProps) {
  const currentTreatment = value?.treatment || 'none';
  const currentIntensity = value?.intensity || 'medium';
  const currentTarget = value?.target || 'all';

  const handleTreatmentChange = (treatment: VisualTreatmentType) => {
    onChange({
      treatment,
      intensity: currentIntensity,
      target: currentTarget,
    });
  };

  const handleIntensityChange = (intensity: TreatmentIntensity) => {
    if (value) {
      onChange({
        ...value,
        intensity,
      });
    }
  };

  const handleTargetChange = (target: typeof currentTarget) => {
    if (value) {
      onChange({
        ...value,
        target,
      });
    }
  };

  // Group treatments by category
  const groupedTreatments = TREATMENTS.reduce((acc, treatment) => {
    if (!acc[treatment.category]) {
      acc[treatment.category] = [];
    }
    acc[treatment.category].push(treatment);
    return acc;
  }, {} as Record<string, typeof TREATMENTS>);

  return (
    <div className="space-y-4">
      {/* Treatment Type */}
      <div>
        <label className="block text-sm font-medium text-gray-200 mb-2">
          Treatment Type
        </label>
        <div className="space-y-3">
          {Object.entries(groupedTreatments).map(([category, treatments]) => (
            <div key={category}>
              <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2">
                {category}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {treatments.map((treatment) => (
                  <button
                    key={treatment.id}
                    onClick={() => handleTreatmentChange(treatment.id)}
                    className={`
                      relative p-3 rounded-lg border-2 transition-all text-left
                      ${currentTreatment === treatment.id
                        ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                        : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                      }
                    `}
                    style={{
                      '--pillar-color': pillarColor,
                    } as React.CSSProperties}
                  >
                    <div className="font-medium text-sm text-gray-100">
                      {treatment.label}
                    </div>
                    <div className="text-xs text-gray-400 mt-1">
                      {treatment.description}
                    </div>
                    {currentTreatment === treatment.id && (
                      <div
                        className="absolute top-2 right-2 w-2 h-2 rounded-full"
                        style={{ backgroundColor: pillarColor }}
                      />
                    )}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Intensity */}
      {currentTreatment !== 'none' && (
        <>
          <div>
            <label className="block text-sm font-medium text-gray-200 mb-2">
              Intensity
            </label>
            <div className="flex gap-2">
              {INTENSITIES.map((intensity) => (
                <button
                  key={intensity}
                  onClick={() => handleIntensityChange(intensity)}
                  className={`
                    flex-1 px-4 py-2 rounded-lg border-2 transition-all capitalize text-sm
                    ${currentIntensity === intensity
                      ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10 text-gray-100'
                      : 'border-gray-700 bg-gray-800/50 text-gray-400 hover:border-gray-600'
                    }
                  `}
                  style={{
                    '--pillar-color': pillarColor,
                  } as React.CSSProperties}
                >
                  {intensity}
                </button>
              ))}
            </div>
          </div>

          {/* Target */}
          <div>
            <label className="block text-sm font-medium text-gray-200 mb-2">
              Target
            </label>
            <div className="flex gap-2 flex-wrap">
              {TARGETS.map((target) => (
                <button
                  key={target}
                  onClick={() => handleTargetChange(target)}
                  className={`
                    px-4 py-2 rounded-lg border-2 transition-all capitalize text-sm
                    ${currentTarget === target
                      ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10 text-gray-100'
                      : 'border-gray-700 bg-gray-800/50 text-gray-400 hover:border-gray-600'
                    }
                  `}
                  style={{
                    '--pillar-color': pillarColor,
                  } as React.CSSProperties}
                >
                  {target}
                </button>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}