import React from 'react';
import { useCanvasStore } from '@/store/canvas-store';
import { cn } from '@/lib/utils';

/**
 * Toolbar component props
 */
interface ToolbarProps {
  className?: string;
  onFitToScreen?: () => void;
  onToggleSnapGrid?: () => void;
  snapGridEnabled?: boolean;
}

/**
 * Toolbar - Main toolbar for canvas editor
 *
 * Phase 3 Update: Removed undo/redo and delete functionality
 * These were for canvas elements only, which are now computed from carousel-store.
 *
 * Features:
 * - Tool selection (select, text, image, hand)
 * - Zoom controls
 * - Snap grid toggle
 *
 * Note: Undo/redo and delete should be implemented at carousel-store level
 * for slide-level operations, not canvas element operations.
 */
export const Toolbar: React.FC<ToolbarProps> = ({
  className,
  onFitToScreen,
  onToggleSnapGrid,
  snapGridEnabled = false,
}) => {
  const {
    activeTool,
    setActiveTool,
    zoom,
    setZoom,
  } = useCanvasStore();

  /**
   * Handle tool selection
   */
  const handleToolSelect = (tool: 'select' | 'text' | 'image' | 'hand') => {
    setActiveTool(tool);
  };

  /**
   * Handle zoom in
   */
  const handleZoomIn = () => {
    const newZoom = Math.min(zoom * 1.25, 5);
    setZoom(newZoom);
  };

  /**
   * Handle zoom out
   */
  const handleZoomOut = () => {
    const newZoom = Math.max(zoom / 1.25, 0.1);
    setZoom(newZoom);
  };

  /**
   * Handle zoom slider change
   */
  const handleZoomChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newZoom = parseFloat(e.target.value);
    setZoom(newZoom);
  };

  /**
   * Get zoom percentage
   */
  const zoomPercentage = Math.round(zoom * 100);

  return (
    <div className={cn(
      'bg-black/20 backdrop-blur-xl border border-white/10 rounded-2xl p-3',
      'flex items-center gap-2',
      className
    )}>
      {/* Tool Selection */}
      <div className="flex items-center gap-1 pr-3 border-r border-white/10">
        <Tooltip content="Select Tool (V)">
          <ToolButton
            icon={<SelectIcon />}
            active={activeTool === 'select'}
            onClick={() => handleToolSelect('select')}
            aria-label="Select tool"
          />
        </Tooltip>

        <Tooltip content="Text Tool (T)">
          <ToolButton
            icon={<TextIcon />}
            active={activeTool === 'text'}
            onClick={() => handleToolSelect('text')}
            aria-label="Text tool"
          />
        </Tooltip>

        <Tooltip content="Image Tool (I)">
          <ToolButton
            icon={<ImageIcon />}
            active={activeTool === 'image'}
            onClick={() => handleToolSelect('image')}
            aria-label="Image tool"
          />
        </Tooltip>

        <Tooltip content="Hand Tool (H)">
          <ToolButton
            icon={<HandIcon />}
            active={activeTool === 'hand'}
            onClick={() => handleToolSelect('hand')}
            aria-label="Hand tool"
          />
        </Tooltip>
      </div>

      {/* Zoom Controls */}
      <div className="flex items-center gap-2 pr-3 border-r border-white/10">
        <Tooltip content="Zoom Out (-)">
          <ToolButton
            icon={<ZoomOutIcon />}
            active={false}
            onClick={handleZoomOut}
            disabled={zoom <= 0.1}
            aria-label="Zoom out"
          />
        </Tooltip>

        <div className="flex items-center gap-2 px-2">
          <span className="text-white/70 text-sm font-mono min-w-[4rem] text-center">
            {zoomPercentage}%
          </span>
          <input
            type="range"
            min="10"
            max="500"
            value={zoomPercentage}
            onChange={handleZoomChange}
            className="w-24 h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-cyan-400"
            aria-label="Zoom level"
          />
        </div>

        <Tooltip content="Zoom In (+)">
          <ToolButton
            icon={<ZoomInIcon />}
            active={false}
            onClick={handleZoomIn}
            disabled={zoom >= 5}
            aria-label="Zoom in"
          />
        </Tooltip>

        <Tooltip content="Fit to Screen (F)">
          <ToolButton
            icon={<FitIcon />}
            active={false}
            onClick={onFitToScreen || (() => {})}
            disabled={!onFitToScreen}
            aria-label="Fit to screen"
          />
        </Tooltip>
      </div>

      {/* Snap Grid Toggle */}
      <div className="flex items-center gap-1">
        <Tooltip content={`Snap Grid ${snapGridEnabled ? 'On' : 'Off'} (G)`}>
          <ToolButton
            icon={<GridIcon />}
            active={snapGridEnabled}
            onClick={onToggleSnapGrid || (() => {})}
            disabled={!onToggleSnapGrid}
            aria-label="Toggle snap grid"
          />
        </Tooltip>
      </div>
    </div>
  );
};

/**
 * ToolButton - Button component for toolbar tools
 */
interface ToolButtonProps {
  icon: React.ReactNode;
  active?: boolean;
  disabled?: boolean;
  danger?: boolean;
  onClick: () => void;
  'aria-label': string;
}

const ToolButton: React.FC<ToolButtonProps> = ({
  icon,
  active = false,
  disabled = false,
  danger = false,
  onClick,
  'aria-label': ariaLabel,
}) => {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      aria-label={ariaLabel}
      className={cn(
        'p-2 rounded-lg transition-all duration-200',
        'flex items-center justify-center',
        'min-w-[36px] min-h-[36px]',
        // Base styles
        !disabled && !active && !danger && 'bg-white/5 text-white/70 hover:bg-white/10 hover:text-white',
        // Active styles
        active && 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30',
        // Danger styles
        danger && !disabled && 'bg-red-500/20 text-red-400 hover:bg-red-500/30',
        // Disabled styles
        disabled && 'bg-white/5 text-white/30 cursor-not-allowed opacity-50',
        // Icon styles
        'w-9 h-9'
      )}
    >
      {icon}
    </button>
  );
};

/**
 * Tooltip - Simple tooltip component
 */
interface TooltipProps {
  content: string;
  children: React.ReactNode;
}

const Tooltip: React.FC<TooltipProps> = ({ content, children }) => {
  return (
    <div className="relative group">
      {children}
      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 bg-black/90 text-white text-xs rounded whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
        {content}
        <div className="absolute top-full left-1/2 -translate-x-1/2 -mt-0.5 border-4 border-transparent border-t-black/90" />
      </div>
    </div>
  );
};

